def move_one_ball(arr):
    # Check if the array is empty or has only one element
    if len(arr) <= 1:
        return True

    # Find the minimum element in the array
    min_val = min(arr)

    # Count the occurrences of the minimum element
    min_count = arr.count(min_val)

    # If there's more than one occurrence of the minimum element,
    # it's impossible to sort the array using right shifts
    if min_count > 1:
        return False

    # If the minimum element is at the beginning of the array,
    # we need to check if the rest of the array is sorted
    if arr.index(min_val) == 0:
        return arr[1:] == sorted(arr[1:])

    # Otherwise, we need to check if the rest of the array is sorted
    # after removing the first occurrence of the minimum element
    return arr[:-min_count] + sorted(arr[min_count:]) == sorted(arr)

def Strongest_Extension(class_name, extensions):
    def calculate_strength(extension):
        cap = sum(1 for char in extension if char.isupper())
        sm = sum(1 for char in extension if char.islower())
        return cap - sm

    max_strength = float('-inf')
    strongest_extension = None

    for extension in extensions:
        current_strength = calculate_strength(extension)
        if current_strength > max_strength:
            max_strength = current_strength
            strongest_extension = extension

    return f"{class_name}.{strongest_extension}"

