import re
def valid_date(date):
    # Regular expression pattern for validating date
    pattern = r"^(0[1-9]|[12][0-9]|3[01])-(0[1-9]|1[012])-([0-9]{4})$"

    # Check if the date matches the pattern
    if re.match(pattern, date):
        # Extract day, month, year from the date string
        day, month, year = map(int, date.split('-'))

        # Check if the month is valid
        if month < 1 or month > 12:
            return False

        # Check if the day is valid based on the month
        if month in [1, 3, 5, 7, 8, 10, 12] and day < 1 or day > 31:
            return False
        elif month in [4, 6, 9, 11] and day < 1 or day > 30:
            return False
        elif month == 2 and (day < 1 or day > 29):
            return False

        return True
    else:
        return False

def match_parens(lst):
    """
    Check if concatenating two strings from the given list can form a balanced string of parentheses.

    Args:
    lst (list): A list containing two strings consisting only of '(' and ')'.

    Returns:
    str: 'Yes' if a balanced string can be formed, 'No' otherwise.
    """
    # Count the number of opening and closing parentheses in each string
    def count_parentheses(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Try concatenating in both orders
    for i in range(len(lst)):
        if count_parentheses(lst[i]) and count_parentheses(lst[(i + 1) % len(lst)]):
            return 'Yes'
    return 'No'

