def reverse_delete(s, c):
    # Remove characters from s that are present in c
    filtered_s = ''.join([char for char in s if char not in c])

    # Check if the resulting string is a palindrome
    is_palindrome = filtered_s == filtered_s[::-1]

    return (filtered_s, is_palindrome)

def get_closest_vowel(word):
    vowels = 'aeiouAEIOU'
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels and word[i-1] not in vowels and word[i+1] not in vowels:
            return word[i]
    return ""

def decimal_to_binary(decimal):
    """Converts a decimal number to its binary representation as a string."""
    if decimal == 0:
        return "db0db"

    binary_str = ""
    while decimal > 0:
        remainder = decimal % 2
        binary_str = str(remainder) + binary_str
        decimal //= 2

    return f"db{binary_str}db"

