def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 

    fix_spaces("Example") == "Example"
    fix_spaces("Example 1") == "Example_1"
    fix_spaces(" Example 2") == "_Example_2"
    fix_spaces(" Example   3") == "_Example-3"
    """
    result = []
    space_count = 0

    for char in text:
        if char == ' ':
            space_count += 1
        else:
            if space_count > 2:
                result.append('-' * space_count)
            elif space_count > 0:
                result.append('_' * space_count)
            space_count = 0
            result.append(char)

    # Handle trailing spaces
    if space_count > 2:
        result.append('-' * space_count)
    elif space_count > 0:
        result.append('_' * space_count)

    return ''.join(result)

def is_happy(s):
    """Check if the string is happy."""
    # Check if the string length is less than 3
    if len(s) < 3:
        return False

    # Iterate through the string to check for consecutive duplicates
    for i in range(len(s) - 2):
        if s[i] == s[i + 1] or s[i] == s[i + 2]:
            return False

    return True

def prod_signs(arr):
    if not arr:
        return None

    # Calculate the product of all signs
    sign_product = 1
    for num in arr:
        if num == 0:
            return 0
        elif num < 0:
            sign_product *= -1

    # Calculate the sum of magnitudes multiplied by the product of signs
    result = sum(abs(num) * sign_product for num in arr)

    return result

