def reverse_vowels(s):
    # Define a set of vowels for quick lookup
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}

    # Convert the string into a list of characters
    s_list = list(s)

    # Initialize two pointers: one at the start and one at the end of the list
    left, right = 0, len(s_list) - 1

    # Loop until the two pointers meet or cross each other
    while left < right:
        # Move the left pointer forward if it points to a non-vowel
        if s_list[left] not in vowels:
            left += 1
        # Move the right pointer backward if it points to a non-vowel
        elif s_list[right] not in vowels:
            right -= 1
        # Swap the vowels at the current positions
        else:
            s_list[left], s_list[right] = s_list[right], s_list[left]
            left += 1
            right -= 1

    # Join the list back into a string and return it
    return ''.join(s_list)

